import type { APIContext } from 'astro';

export const prerender = true;

export function GET({ site }: APIContext) {
	const base = site ?? new URL('https://blog.wfrlee.com');
	const sitemap = new URL('sitemap-index.xml', base).toString();

	const body = `# robots.txt for Wfrlee.com
User-agent: *
Allow: /

# Keep crawlers out of non-public surfaces.
Disallow: /admin/
Disallow: /drafts/
Disallow: /styleguide/

# Sitemap index generated by @astrojs/sitemap
Sitemap: ${sitemap}
`;

	return new Response(body, {
		headers: {
			'Content-Type': 'text/plain; charset=utf-8',
		},
	});
}
